  "description": "The claude CLI as the agent, over its JSON envelope.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "plugins/claude"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "amy": {
    "about": "Use it when the agent should be Claude Code, run through the claude CLI. It contributes a harness and a usage reader to agent-relay instead of mounting the agent port itself, so install agent-relay with it, and list codex or hermes-agent too when the relay should have somewhere to fall back. Claude reports what each run cost, so a ceiling in money works without a row in the price table."
  },
  "dependencies": {
    "@amykit/agent-kit": "^0.8.0",
    "@amykit/core": "^0.8.0",
    "@amykit/model-specs": "^0.8.0"
  },
  "devDependencies": {
    "@amykit/test-fixtures": "^0.1.0"
  }
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AgentRun, AskContext, CommandRunner, Harness, HarnessReply } from "@amykit/core";
import { costOf, specFor } from "@amykit/model-specs";
import { ParsedRun, parseRun } from "./envelope.js";

export interface ClaudeHarnessConfig {
  /** Passed to the CLI as --model. Omit to use whatever the CLI defaults to. */
  model?: string;
  /** What a run that may write passes as --permission-mode; `acceptEdits` unless set. */
  permissionMode?: WritingMode;
  timeoutMs?: number;
}

/**
 * The permission modes under which a print-mode run can write.
 *
 * With the user's settings dropped, no allow rule reaches the run, so
 * `default` and `dontAsk` deny every edit and `plan` blocks them: a writing
 * run handed one of those answers and changes nothing.
 * https://code.claude.com/docs/en/permission-modes
 */
export const WRITING_MODES = ["acceptEdits", "auto", "bypassPermissions"] as const;
export type WritingMode = (typeof WRITING_MODES)[number];

/** The configured mode, or why it is refused, naming the setting. */
export function writingMode(value: unknown): WritingMode {
  if (typeof value === "string" && (WRITING_MODES as readonly string[]).includes(value)) return value as WritingMode;
  throw new Error(
    `permissionMode is ${JSON.stringify(value ?? "")}, under which a run cannot write: ` +
      `set it to ${WRITING_MODES.map((mode) => `\`${mode}\``).join(", ")}`,
  );
}

/**
 * What keeps a run apart from the operator's own Claude.
 *
 * Without these a ticket run read the operator's personal CLAUDE.md, every
 * skill they had installed, their hooks and plugins, and kept a session and
 * an auto-memory under `~/.claude/projects`. The repository's own settings —
 * `project` and `local` — still load: they belong to the code being worked
 * on, not to the person running amy.
 */
export const ISOLATED = [
  "--setting-sources",
  "project,local",
  "--strict-mcp-config",
  "--no-session-persistence",
] as const;

/**
 * Lends one skill to a run: a fresh directory whose `.claude/skills/<name>`
 * links to where the skill is installed, for `--add-dir`.
 *
 * Dropping the user setting source drops `~/.claude/skills` with it, so the
 * skill a step was addressed to is handed over by place, and nothing else of
 * the operator's comes along. A skill whose directory is gone is not lent,
 * and the run goes ahead without it.
 */
export function lend(tmpDir: string, skill: { name: string; path: string }): string | undefined {
  // Absolute, since a link is read from where it lies: a relative skill root
  // would otherwise point inside the lent directory and lend nothing.
  const source = path.resolve(skill.path);
  if (!fs.existsSync(path.join(source, "SKILL.md"))) return undefined;

  const root = fs.mkdtempSync(path.join(tmpDir, "amy-claude-skill-"));
  const skills = path.join(root, ".claude", "skills");
  fs.mkdirSync(skills, { recursive: true });
  fs.symlinkSync(source, path.join(skills, skill.name), "dir");
  return root;
}

/**
 * The `claude` CLI, and everything knowable about what a call to it took.
 *
 * `--output-format stream-json` is what makes the run measurable rather than
 * guessed: the result line returns the answer, the token counts, the cost the
 * harness itself worked out and an error status to classify on, and the
 * `rate_limit_event` before it says when the plan refused the turn and when
 * the quota resets.
 */
export class ClaudeHarness implements Harness {
  readonly name = "claude";
  /** It is handed a skill by place: a fresh `--add-dir` whose skills link to it. */
  readonly lendsSkill = true;
  /** The operator's own skills, where Claude Code installs them. */
  readonly skillsDirectory = path.join(os.homedir(), ".claude", "skills");

  constructor(
    private readonly runner: CommandRunner,
    private readonly config: ClaudeHarnessConfig = {},
    private readonly tmpDir: string = os.tmpdir(),
  ) {}

  async ask(prompt: string, cwd: string, context: AskContext = {}): Promise<HarnessReply> {
    const asked = this.config.model ?? "";
    const args: string[] = [];
    if (this.config.model) {
      args.push("--model", this.config.model);
    }
    // Plan mode reads and does not edit or run anything, enforced by the CLI.
    // A mode is always passed: with no mode a print-mode run may not write.
    args.push("--permission-mode", context.readOnly ? "plan" : (this.config.permissionMode ?? "acceptEdits"));
    args.push(...ISOLATED);

    const lent = context.skill ? lend(this.tmpDir, context.skill) : undefined;
    if (lent) args.push("--add-dir", lent);
    args.push("--output-format", "stream-json", "--verbose", "-p");

    const started = Date.now();
    let result: Awaited<ReturnType<CommandRunner["run"]>>;
    try {
      result = await this.runner.run("claude", args, {
        cwd,
        stdin: prompt,
        timeoutMs: this.config.timeoutMs,
      });
    } finally {
      if (lent) fs.rmSync(lent, { recursive: true, force: true });
    }
    const elapsed = Date.now() - started;

    const parsed = parseRun(result.stdout, result.ok, asked);
    return { text: parsed.text, run: this.account(parsed, elapsed, result.stderr) };
  }

  /**
   * Turns a parsed run into the account the engine logs and the budget spends.
   *
   * A cost the harness reported wins, because it knows the plan and the
   * discounts. Failing that, the vendored table computes one and says so. A
   * model the table has never heard of leaves the cost absent rather than
   * inventing a rate to spend against a ceiling.
   */
  private account(parsed: ParsedRun, elapsedMs: number, stderr: string): AgentRun {
    let costUsd = parsed.costUsd;
    let costSource = parsed.costSource;

    if (costUsd === undefined && parsed.tokens) {
      const spec = specFor(parsed.model);
      if (spec) {
        costUsd = costOf(spec, parsed.tokens);
        costSource = "computed";
      }
    }

    return {
      outcome: parsed.outcome,
      harness: this.name,
      model: parsed.model,
      tokens: parsed.tokens,
      costUsd,
      costSource,
      durationMs: parsed.durationMs ?? elapsedMs,
      ...(parsed.retryAfterMs === undefined ? {} : { retryAfterMs: parsed.retryAfterMs }),
      output: [parsed.text, stderr].filter(Boolean).join("\n").trim(),
    };
  }
}

import { ConfigSchema } from "@amykit/core";

/** What this plugin needs told to it, and nothing more. */
export const configSchema = {
  model: {
    type: "string",
    description: "passed to the CLI as --model, which is the flag it accepts",
    default: "",
  },
  models: {
    type: "string[]",
    description:
      "the model tiers to offer the relay, cheapest first. One agent is contributed per tier, named `claude:<model>`. Empty means a single agent using `model`",
    default: [],
  },
  permissionMode: {
    type: "string",
    description:
      "passed to the CLI as --permission-mode on a run that may write: `acceptEdits`, `auto` or `bypassPermissions`. A read-only run is always `plan`",
    default: "acceptEdits",
  },
  timeoutMs: {
    type: "number",
    description: "how long one agent call may run before it is given up on",
    default: 30 * 60 * 1000,
  },
} satisfies ConfigSchema;

import { AgentOutcome, CostSource, TokenUsage } from "@amykit/core";

/** The shape `claude -p --output-format json` prints. */
export interface ClaudeEnvelope {
  result?: string;
  is_error?: boolean;
  api_error_status?: number | string | null;
  stop_reason?: string | null;
  total_cost_usd?: number;
  duration_ms?: number;
  usage?: {
    input_tokens?: number;
    output_tokens?: number;
    cache_read_input_tokens?: number;
    cache_creation_input_tokens?: number;
    /**
     * How the cache writes split by time to live.
     *
     * This is present in real envelopes and matters: a one-hour write is
     * billed at twice the input rate, so ignoring the split undercounts a
     * cache-heavy run badly. One real run had all 10,232 of its cache writes
     * at one hour, which is a 60% difference in the computed cost.
     */
    cache_creation?: {
      ephemeral_1h_input_tokens?: number;
      ephemeral_5m_input_tokens?: number;
    };
  };
  modelUsage?: Record<string, unknown>;
}

/**
 * What a `--output-format stream-json` run said, read after it exits.
 *
 * The stream prints one JSON event a line. The last `result` event is the
 * envelope `--output-format json` would have printed, and a `rate_limit_event`
 * whose `rate_limit_info.status` is `rejected` is the plan refusing the turn,
 * whatever the result line says.
 */
export interface ClaudeStream {
  /** The envelope the stream carried, when it carried one. */
  result: ClaudeEnvelope | null;
  /** A rate_limit_event said the plan refused this turn. */
  rejected: boolean;
  /** A result line reported a 429, wherever in the stream it was. */
  throttled: boolean;
  /** The epoch-second reset that event reported, when it reported one. */
  resetsAt?: number;
}

export interface ParsedRun {
  outcome: AgentOutcome;
  text: string;
  model: string;
  tokens?: TokenUsage;
  costUsd?: number;
  costSource: CostSource;
  durationMs?: number;
  /** How long the plan said the wait lasts, when a rejected event said. */
  retryAfterMs?: number;
}

/**
 * Reads the envelope, or says it could not.
 *
 * Returns null rather than throwing, because a harness that printed something
 * unexpected is a run to classify, not an exception to unwind.
 */
export function parseEnvelope(stdout: string): ClaudeEnvelope | null {
  const trimmed = stdout.trim();
  if (!trimmed.startsWith("{")) return null;

  try {
    return JSON.parse(trimmed) as ClaudeEnvelope;
  } catch {
    return null;
  }
}

/**
 * Reads a `stream-json` run, one JSON event a line.
 *
 * A line that is not JSON is skipped: the run is read from the lines that are,
 * which is what the json format did with anything that was not an envelope.
 * The last `result` event wins, because that is the envelope the run ended
 * with, and the last rejected event wins for the same reason.
 */
export function parseStream(stdout: string): ClaudeStream {
  let result: ClaudeEnvelope | null = null;
  let rejected = false;
  let throttled = false;
  let resetsAt: number | undefined;

  for (const line of stdout.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed.startsWith("{")) continue;

    let event: Record<string, unknown>;
    try {
      event = JSON.parse(trimmed) as Record<string, unknown>;
    } catch {
      continue;
    }

    if (event.type === "result") {
      result = event as ClaudeEnvelope;
      if (isRateLimit((event as ClaudeEnvelope).api_error_status)) throttled = true;
    }
    if (event.type !== "rate_limit_event") continue;

    const refusal = refusalOf(event);
    if (!refusal) continue;

    rejected = true;
    // The latest reset any refusal reported: two windows can refuse at once
    // and a step may only rerun once every one of them reopened, so an event
    // that reports no reset must not erase the one another named.
    if (refusal.resetsAt !== undefined) {
      resetsAt = resetsAt === undefined ? refusal.resetsAt : Math.max(resetsAt, refusal.resetsAt);
    }
  }

  return { result, rejected, throttled, ...(resetsAt === undefined ? {} : { resetsAt }) };
}

/**
 * The refusal a `rate_limit_event` reports, or nothing when it reports none.
 *
 * Only `status: "rejected"` refuses, and only while the window is not carried
 * by usage credits: an `overageStatus` of anything but absent or `"rejected"`
 * (`"allowed"`, `"allowed_warning"`) says credits carried the turn, which then
 * finished, so there is nothing to wait for.
 */
function refusalOf(event: Record<string, unknown>): { resetsAt?: number } | undefined {
  const info = event.rate_limit_info as
    | { status?: unknown; resetsAt?: unknown; overageStatus?: unknown }
    | undefined;
  if (info?.status !== "rejected") return undefined;
  if (info.overageStatus !== undefined && info.overageStatus !== "rejected") return undefined;

  const resetsAt = typeof info.resetsAt === "number" && Number.isFinite(info.resetsAt) ? info.resetsAt : undefined;
  return resetsAt === undefined ? {} : { resetsAt };
}

/**
 * Which of the four outcomes this run was.
 *
 * Read off the envelope, not off stderr. A rate limit and a failure want
 * opposite responses, and guessing between them from log text is how a relay
 * ends up escalating to an expensive model over a quota problem.
 */
export function classify(envelope: ClaudeEnvelope | null, exitOk: boolean): AgentOutcome {
  if (!envelope) return exitOk ? "completed" : "abandoned";

  if (isRateLimit(envelope.api_error_status)) return "rate-limited";
  if (envelope.is_error === true || !exitOk) return "failed";

  return "completed";
}

/**
 * The outcome of a whole stream.
 *
 * A rejected `rate_limit_event` settles it before anything else is read: the
 * plan refusing a turn is a quota answer whatever the result line says, and a
 * run killed right after the refusal is still a limit rather than an
 * abandoned run that would start another child over the same quota.
 */
export function classifyStream(stream: ClaudeStream, exitOk: boolean): AgentOutcome {
  if (stream.rejected || stream.throttled) return "rate-limited";
  return classify(stream.result, exitOk);
}

/**
 * How long the stream said to wait, in milliseconds.
 *
 * Absent rather than zero when the reset is missing, unreadable or already in
 * the past: the policy's own backoff is the honest answer then, and a zero
 * wait would rerun into the same refusal.
 */
export function retryAfterOf(stream: ClaudeStream, now = Date.now()): number | undefined {
  if (!stream.rejected || stream.resetsAt === undefined) return undefined;

  const wait = stream.resetsAt * 1000 - now;
  return wait > 0 ? wait : undefined;
}

function isRateLimit(status: number | string | null | undefined): boolean {
  if (status === undefined || status === null) return false;
  if (typeof status === "number") return status === 429;
  return status.includes("429");
}

/**
 * What the CLI printed that was not an event line.
 *
 * A stream that ended without a result line has no answer to hand back, and
 * its events are not one: they carry tool calls and tool results, file
 * contents among them, and a rerun would fold all of that into its prompt.
 */
function prose(stdout: string): string {
  const kept = stdout.split("\n").filter((line) => line.trim() !== "" && !line.trim().startsWith("{"));
  return kept.join("\n").trim();
}

/** The token counts, if the envelope carried them. */
export function tokensOf(envelope: ClaudeEnvelope | null): TokenUsage | undefined {
  const usage = envelope?.usage;
  if (!usage) return undefined;

  const oneHour = usage.cache_creation?.ephemeral_1h_input_tokens;

  return {
    input: usage.input_tokens ?? 0,
    output: usage.output_tokens ?? 0,
    cacheRead: usage.cache_read_input_tokens ?? 0,
    cacheWrite: usage.cache_creation_input_tokens ?? 0,
    ...(oneHour === undefined ? {} : { cacheWrite1h: oneHour }),
  };
}

/**
 * The model the run actually used.
 *
 * `modelUsage` is keyed by it, decorations and all, which is more truthful
 * than what was asked for: a fallback would have changed it.
 */
export function modelOf(envelope: ClaudeEnvelope | null, asked: string): string {
  const keys = Object.keys(envelope?.modelUsage ?? {});
  return keys[0] ?? asked;
}

export function parseRun(stdout: string, exitOk: boolean, asked: string, now = Date.now()): ParsedRun {
  const stream = parseStream(stdout);
  const envelope = stream.result;
  const tokens = tokensOf(envelope);
  const reported = envelope?.total_cost_usd;
  const retryAfterMs = retryAfterOf(stream, now);

  return {
    outcome: classifyStream(stream, exitOk),
    // The envelope puts the answer in `result`; without one, the CLI's prose
    // is all there is, never the events themselves.
    text: envelope?.result ?? prose(stdout),
    model: modelOf(envelope, asked),
    tokens,
    costUsd: typeof reported === "number" ? reported : undefined,
    // The harness knows the plan and the discounts, so what it says beats
    // anything worked out from a price table.
    // Only ever `reported` or `unknown` here. Working a cost out from a
    // price table is the caller's job, and claiming `computed` without
    // computing would be the exact confusion `costSource` exists to prevent.
    costSource: typeof reported === "number" ? "reported" : "unknown",
    durationMs: envelope?.duration_ms,
    ...(retryAfterMs === undefined ? {} : { retryAfterMs }),
  };
}

export { ClaudeHarness, ISOLATED, WRITING_MODES, lend, writingMode } from "./ClaudeHarness.js";
export type { ClaudeHarnessConfig, WritingMode } from "./ClaudeHarness.js";
export { classify, modelOf, parseEnvelope, parseRun, tokensOf } from "./envelope.js";
export type { ClaudeEnvelope, ParsedRun } from "./envelope.js";
export { configSchema } from "./config.js";
export { plugin } from "./plugin.js";
export { ClaudeUsageReader, parseClaudeUsage } from "./usage.js";
export type { ClaudeUsageReaderOptions } from "./usage.js";

import { definePlugin } from "@amykit/core";
import { contributeTiers, contributeUsage } from "@amykit/agent-kit";
import { ClaudeHarness, writingMode } from "./ClaudeHarness.js";
import { configSchema } from "./config.js";
import { ClaudeUsageReader } from "./usage.js";

export const plugin = definePlugin<typeof configSchema>({
  name: "@amykit/plugin-claude",
  configSchema,
  register(registry, ctx) {
    const tiers = ctx.config.models;
    // Refused here, at mount, rather than as a run that answers and edits nothing.
    const permissionMode = writingMode(ctx.config.permissionMode);

    // Contributed rather than mounted as the `agent` port: only one plugin
    // can own a port, and three harnesses that each wanted to be *the* agent
    // would refuse to mount together. The relay composes what is contributed.
    contributeTiers(registry, {
      harness: "claude",
      // The envelope carries `total_cost_usd`, and a cost the harness
      // reported beats anything a table could work out, so a missing row
      // never leaves a ceiling in money with nothing to spend against it.
      pricesItsOwnRuns: true,
      models: tiers.length > 0 ? tiers : [(ctx.config.model) || ""],
      make: (model) =>
        new ClaudeHarness(ctx.runner, {
          model: model || undefined,
          permissionMode,
          timeoutMs: ctx.config.timeoutMs,
        }),
    });
    // A usage read is an inspection, not a run: it gets the probe's own short
    // deadline rather than the run timeout, so a hung CLI cannot hold status.
    contributeUsage(registry, new ClaudeUsageReader(ctx.runner));
  },
});

import type { ChildProcessWithoutNullStreams } from "node:child_process";
import { createInterface } from "node:readline";
import { CommandRunner } from "@amykit/core";
import type { UsageReader, UsageResult, UsageWindow } from "@amykit/agent-kit";

export interface ClaudeUsageReaderOptions {
  /** How long Claude Code has to answer, in milliseconds. */
  readonly timeoutMs?: number;
  /** The CLI to ask; a test points it at a stand-in. */
  readonly command?: string;
}

/**
 * Claude Code with nothing of the operator's own: no settings, hooks, MCP
 * servers or kept session. Print mode with stream-json input is what lets a
 * control request reach it with no prompt.
 */
export const CLAUDE_PROBE_ARGS = [
  "-p",
  "--input-format",
  "stream-json",
  "--output-format",
  "stream-json",
  "--verbose",
  "--setting-sources",
  "",
  "--strict-mcp-config",
  "--no-session-persistence",
] as const;

/** How long Claude Code has to answer `get_usage`; a probe reads, it never runs. */
const DEFAULT_TIMEOUT_MS = 15_000;

/** How much of what Claude Code wrote to stderr is kept to say why it ended. */
const STDERR_KEPT = 400;

/** The windows `get_usage` reports, and the label each is shown under. */
const WINDOWS = [
  ["five_hour", "five-hour"],
  ["seven_day", "seven-day"],
  ["seven_day_opus", "seven-day-opus"],
  ["seven_day_sonnet", "seven-day-sonnet"],
] as const;

/**
 * Reads Claude's account windows by asking Claude Code itself.
 *
 * The token, the Keychain item and the credentials file stay Claude Code's:
 * `get_usage` is a control request over a short-lived print-mode child, so no
 * model call and no agent turn happens. A runner without a managed spawn
 * cannot hold that child open, and reads as unavailable.
 */
export class ClaudeUsageReader implements UsageReader {
  readonly label = "Claude";

  constructor(
    private readonly runner: CommandRunner,
    private readonly options: ClaudeUsageReaderOptions = {},
  ) {}

  async read(): Promise<UsageResult> {
    const spawn = this.runner.spawn;
    if (!spawn) return unavailable("this runner cannot start claude");
    try {
      return await probe(spawn.bind(this.runner), this.options);
    } catch (error) {
      return unavailable(reason(error));
    }
  }
}

/** Normalizes a `get_usage` answer; a plan whose limits do not apply has none. */
export function parseClaudeUsage(response: unknown): UsageResult {
  if (!record(response)) return unavailable("get_usage returned no answer");
  if (response.rate_limits_available === false) return unavailable("Claude Code reports no rate limits for this sign-in");
  const limits = record(response.rate_limits) ? response.rate_limits : undefined;
  if (response.rate_limits_available !== true || !limits) return unavailable("Claude Code did not report rate limits");

  const windows = WINDOWS.flatMap(([key, label]) => {
    const window = windowOf(label, limits[key]);
    return window ? [window] : [];
  });
  return windows.length > 0 ? { windows } : unavailable("Claude Code reported no measured windows");
}

type Spawn = NonNullable<CommandRunner["spawn"]>;

/** One short-lived CLI, asked for its windows and ended once it answers. */
function probe(spawn: Spawn, options: ClaudeUsageReaderOptions): Promise<UsageResult> {
  const command = options.command ?? "claude";
  return new Promise((resolve) => {
    let child: ChildProcessWithoutNullStreams;
    try {
      // Its own process group, so one signal ends what the probe started.
      child = spawn(command, [...CLAUDE_PROBE_ARGS], { detached: process.platform !== "win32" });
    } catch (error) {
      resolve(unavailable(`could not start ${command}: ${reason(error)}`));
      return;
    }
    new Probe(child, command, options.timeoutMs ?? DEFAULT_TIMEOUT_MS, resolve).start();
  });
}

/** What a `control_response` line carries, as far as this reader reads it. */
interface Answer {
  readonly request_id?: unknown;
  readonly subtype?: unknown;
  readonly response?: unknown;
  readonly error?: unknown;
}

class Probe {
  private answered = false;
  private asked = false;
  private tail = "";
  private readonly timer: ReturnType<typeof setTimeout>;

  constructor(
    private readonly child: ChildProcessWithoutNullStreams,
    private readonly command: string,
    timeoutMs: number,
    private readonly settle: (result: UsageResult) => void,
  ) {
    this.timer = setTimeout(() => this.finish(unavailable(`${command} did not answer in ${timeoutMs}ms`)), timeoutMs);
  }

  start(): void {
    this.child.stdin.on("error", () => {});
    // Nobody reads stderr but it is piped: a chatty CLI fills the pipe, blocks
    // on write, and a healthy answer becomes a timeout. Keep its tail instead.
    this.child.stderr.setEncoding("utf8");
    this.child.stderr.on("data", (chunk: string) => {
      this.tail = `${this.tail}${chunk}`.slice(-STDERR_KEPT);
    });
    this.child.on("error", (error) => this.finish(unavailable(`could not start ${this.command}: ${reason(error)}`)));
    this.child.on("close", () => this.finish(unavailable(`${this.command} ended before answering${this.said()}`)));
    createInterface({ input: this.child.stdout, crlfDelay: Number.POSITIVE_INFINITY }).on("line", (line) =>
      this.onLine(line),
    );
    this.send({ type: "control_request", request_id: "init", request: { subtype: "initialize" } });
  }

  /** The last thing Claude Code said on stderr, on one line, for an early end. */
  private said(): string {
    const last = this.tail
      .split("\n")
      .map((line) => line.trim())
      .filter(Boolean)
      .pop();
    return last ? `: ${last}` : "";
  }

  private send(message: unknown): void {
    try {
      this.child.stdin.write(`${JSON.stringify(message)}\n`);
    } catch {
      // Its end settles the probe.
    }
  }

  private onLine(line: string): void {
    const answer = responseOf(line);
    if (!answer) return;
    if (answer.request_id === "init") this.afterInitialize(answer);
    // Only the answer to what the probe asked is read: anything printed before
    // `get_usage` was sent answers nothing.
    else if (answer.request_id === "usage" && this.asked) this.finish(usageAnswer(answer));
  }

  private afterInitialize(answer: Answer): void {
    if (answer.subtype !== "success") return this.finish(unavailable(`${this.command} answered initialize with ${said(answer)}`));
    this.asked = true;
    this.send({ type: "control_request", request_id: "usage", request: { subtype: "get_usage", skip_behaviors: true } });
  }

  private finish(result: UsageResult): void {
    if (this.answered) return;
    this.answered = true;
    clearTimeout(this.timer);
    endTree(this.child);
    this.settle(result);
  }
}

/** Ends the probe with everything it started: it leads its group, so one signal ends the tree. */
function endTree(child: ChildProcessWithoutNullStreams): void {
  const pid = child.pid;
  if (pid !== undefined && process.platform !== "win32") {
    try {
      process.kill(-pid, "SIGKILL");
      return;
    } catch {
      // Not a group leader: end the child alone.
    }
  }
  child.kill("SIGKILL");
}

/** The answer inside one stream-json line, when the line is a control response. */
function responseOf(line: string): Answer | undefined {
  let message: unknown;
  try {
    message = JSON.parse(line);
  } catch {
    return undefined;
  }
  if (!record(message) || message.type !== "control_response") return undefined;
  return record(message.response) ? message.response : undefined;
}

/** What Claude Code answered a control request with, for a person to read. */
function said(answer: Answer): string {
  const word = typeof answer.subtype === "string" ? answer.subtype : "nothing";
  return typeof answer.error === "string" && answer.error ? `${word}: ${answer.error}` : word;
}

function usageAnswer(answer: Answer): UsageResult {
  if (answer.subtype !== "success") return unavailable(`get_usage was answered with ${said(answer)}`);
  return parseClaudeUsage(answer.response);
}

function windowOf(label: string, value: unknown): UsageWindow | undefined {
  if (!record(value) || typeof value.utilization !== "number" || !Number.isFinite(value.utilization)) return undefined;
  const resetsAt = resetOf(value.resets_at);
  return {
    label,
    usedPercent: Math.max(0, Math.min(100, value.utilization)),
    ...(resetsAt ? { resetsAt } : {}),
  };
}

/** A reset time is an instant: Claude Code sends microseconds and an offset, windows carry ISO. */
function resetOf(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  const at = new Date(value);
  return Number.isNaN(at.getTime()) ? undefined : at.toISOString();
}

function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function unavailable(why: string): UsageResult {
  return { unavailable: `Claude usage is unavailable: ${why}` };
}

function reason(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
